insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('P&N Landscaping & Hardscaping','Home Services','Service area only',null,'(209) 684-8953','https://www.pnscape.com/','Provider advertising landscape and hardscape projects including pavers, concrete, artificial grass and retaining walls. Its official service-area list individually names Mountain House, Tracy, Lathrop and Manteca. No public visitor office is established here. Confirm property eligibility, installation scope, required credentials, quote and appointment directly. Routine lawn maintenance and current availability are not confirmed.','approved',true,false,null,0,'editorial_first_party','https://www.pnscape.com/','first_party_website_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.pnscape.com/',array['identity','website','public phone','advertised landscape installation','explicit named service cities'],array['Mountain House','Tracy','Lathrop','Manteca'],array['landscaping','landscape construction','pavers','artificial turf installation'],'Official website information checked November 8, 2026. No owner contact, independent license/insurance/quality/safety/effectiveness check, photos, price or appointment confirmation. No street address or local branch inferred. Sources: https://www.pnscape.com/ https://www.pnscape.com/');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "P&N Landscaping & Hardscaping", "city": "Service area only", "phone": "(209) 684-8953", "website": "https://www.pnscape.com/", "source_url": "https://www.pnscape.com/", "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "tags": ["landscaping", "landscape construction", "pavers", "artificial turf installation"], "description": "Provider advertising landscape and hardscape projects including pavers, concrete, artificial grass and retaining walls. Its official service-area list individually names Mountain House, Tracy, Lathrop and Manteca. No public visitor office is established here. Confirm property eligibility, installation scope, required credentials, quote and appointment directly. Routine lawn maintenance and current availability are not confirmed."}'::jsonb,'Explicit four-city landscape service website evidence','https://www.pnscape.com/');end $curate$;
commit;
